cles_public'))
SELECT jsonb_build_object(
'sysid',(SELECT system_identifier::text FROM pg_control_system()),
'receipt_20260628200526',(SELECT jsonb_build_object('name',name,'n_statements',coalesce(array_length(statements,1),0),'statements_md5',md5(coalesce(array_to_string(statements,E'\n'),'')),
   'created_objects',(SELECT jsonb_agg(DISTINCT lower(m[1])||' '||lower(m[2])) FROM unnest(statements) s, regexp_matches(s,'create\s+(?:or\s+replace\s+)?(table|function|policy|trigger|index|view|type)\s+(?:if\s+not\s+exists\s+)?("[^"]+"(?:\s+on\s+[\w."]+)?|[\w."]+)','gi') m)) FROM supabase_migrations.schema_migrations WHERE version='20260628200526'),
'receipt_statement_md5s',(SELECT jsonb_object_agg(version, md5(coalesce(array_to_string(statements,E'\n'),''))) FROM supabase_migrations.schema_migrations),
'tables',(SELECT jsonb_object_agg(t.n, CASE WHEN to_regclass('public.'||t.n) IS NULL THEN NULL ELSE md5((SELECT string_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull,',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=to_regclass('public.'||t.n) AND a.attnum>0 AND NOT a.attisdropped)) END) FROM t),
'functions',(SELECT jsonb_object_agg(f.n,(SELECT string_agg(md5(pg_get_functiondef(p.oid)),',' ORDER BY p.oid) FROM pg_proc p JOIN pg_namespace s ON s.oid=p.pronamespace WHERE s.nspname||'.'||p.proname=f.n)) FROM f),
'policies',(SELECT jsonb_object_agg(p.n,(SELECT md5(concat_ws('|',cmd,permissive,roles::text,qual,with_check)) FROM pg_policies x WHERE x.tablename||'|'||x.policyname=p.n)) FROM p),
'triggers',(SELECT jsonb_object_agg(tr.n,(SELECT string_agg(t2.tgrelid::regclass::text||':'||md5(pg_get_triggerdef(t2.oid)),',') FROM pg_trigger t2 WHERE t2.tgname=tr.n AND NOT t2.tgisinternal)) FROM tr),
'columns',(SELECT jsonb_object_agg(c.n,(SELECT format_type(a.atttypid,a.atttypmod) FROM pg_attribute a WHERE a.attrelid=to_regclass('public.'||split_part(c.n,'.',1)) AND a.attname=split_part(c.n,'.',2) AND NOT a.attisdropped)) FROM c),
'indexes',(SELECT jsonb_object_agg(i.n,(SELECT md5(pg_get_indexdef(x.indexrelid)) FROM pg_index x JOIN pg_class ic ON ic.oid=x.indexrelid JOIN pg_namespace s ON s.oid=ic.relnamespace WHERE ic.relname=i.n AND s.nspname='public')) FROM i),
'views',(SELECT jsonb_object_agg(v.n,(SELECT md5(pg_get_viewdef(to_regclass('public.'||v.n)))) ) FROM v)
) AS r;